    23	    public String generate(YearMonth month) {
    24	        List<Reservation> withRevenue = new ArrayList<>();
    25	        for (Reservation reservation : store.all()) {
    26	            boolean keptMoney = reservation.amountKept().signum() > 0;
    27	            boolean startsInMonth = YearMonth.from(reservation.checkIn()).equals(month);
    28	            if (keptMoney && startsInMonth) {
    29	                withRevenue.add(reservation);
    30	            }
    31	        }
    32	        withRevenue.sort(Comparator.comparing(Reservation::checkIn).thenComparingLong(Reservation::id));
    33	
    34	        StringBuilder csv = new StringBuilder();
    35	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    36	        BigDecimal revenue = BigDecimal.ZERO.setScale(2);
